import pandas as pd

data = _items

rows = [item["json"] for item in data]
df = pd.DataFrame(rows)

datasets = []

for _, row in df.iterrows():
    datasets.append({
        "dataset": row["dataset"],
        "clean_rows": int(row["clean_rows"]),
        "total_issues": int(row["total_issues"]),
        "quality_status": row["quality_status"]
    })

total_clean_rows = sum(
    item["clean_rows"] for item in datasets
)

total_dq_issues = sum(
    item["total_issues"] for item in datasets
)

passed_datasets = sum(
    1 for item in datasets
    if item["quality_status"] == "Pass"
)

failed_datasets = sum(
    1 for item in datasets
    if item["quality_status"] == "Fail"
)

overall_quality_status = (
    "Pass" if failed_datasets == 0 else "Fail"
)

return [
    {
        "json": {
            "datasets": datasets,
            "overall_summary": {
                "total_clean_rows": total_clean_rows,
                "total_dq_issues": total_dq_issues,
                "passed_datasets": passed_datasets,
                "failed_datasets": failed_datasets,
                "overall_quality_status": overall_quality_status
            }
        }
    }
]

import json

