    ]

data = _items[0]["json"]

# Dynamic report title 
title = data.get("user_question", "Operational Investigation").upper()

# Evidence
evidence = "\n".join(
    f"• {row['metric']}: {row['value']}"
    for row in data.get("evidence", [])
)

# Recommendation / Recommended Action
actions = data.get("recommendation", data.get("recommended_action", []))
recommendations = "\n".join(
    f"{i}. {item}"
    for i, item in enumerate(actions, 1)
)

# Build report
if "problem" in data:
    report = f"""{title}

PROBLEM
{data.get("problem", "")}

EVIDENCE
{evidence}

PATTERN
{data.get("pattern", "")}

ROOT CAUSE
{data.get("root_cause", "")}

BUSINESS IMPACT
{data.get("business_impact", "")}

RECOMMENDATION
{recommendations}"""
else:
    report = f"""{title}

EXECUTIVE SUMMARY
{data.get("executive_summary", "")}

EVIDENCE
{evidence}

BUSINESS IMPACT
{data.get("business_impact", "")}

RECOMMENDED ACTION
{recommendations}"""

return [{"json": {"output": report}}]

